import React, { useState, useEffect } from 'react';
import { C, font, FREQS, FMTS } from '../theme';
import { TInput, Field, PrimaryBtn, GhostBtn, ErrBox, Divider, Pills, SelectInput } from '../components/UI';
import { bulkApi, templateApi, schemaApi } from '../api';
import FileNamePatternBuilder from '../components/FileNamePatternBuilder';

const POI_DEFAULT = '__poi_default__';

/**
 * Full-page edit form for a Bulk Report Schedule.
 * Covers all fields: template, schedule name, category, frequency,
 * source table/SQL, entity IDs, auto-discover, institution query,
 * JRXML param map, base SQL with tokens, outputFormat, recipients,
 * fileNamingPattern, localOutputPath, notes.
 */
export default function EditBulkSchedulePage({ scheduleId, onSaved, onCancel }) {
  const [templates,  setTemplates]  = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [saving,     setSaving]     = useState(false);
  const [err,        setErr]        = useState('');

  // Form state
  const [platformId,        setPlatformId]        = useState('');
  const [tpl,               setTpl]               = useState(POI_DEFAULT);
  const [scheduleName,      setScheduleName]      = useState('');
  const [category,          setCategory]          = useState('CUSTOM');
  const [frequency,         setFrequency]         = useState('MONTHLY');
  const [runTime,           setRunTime]           = useState('07:00');
  const [outputFormat,      setOutputFormat]      = useState('EXCEL');
  const [recipients,        setRecipients]        = useState('');
  const [notes,             setNotes]             = useState('');
  const [fileNamingPattern, setFileNamingPattern] = useState('{REPORT_NAME}_{ENTITY_ID}_{DATE}');
  const [localOutputPath,   setLocalOutputPath]   = useState('');
  // Entity selection
  const [sourceMode,        setSourceMode]        = useState('manual'); // 'manual' | 'sql'
  const [sourceTable,       setSourceTable]       = useState('');
  const [idColumn,          setIdColumn]          = useState('');
  const [idValues,          setIdValues]          = useState('');
  // Base SQL
  const [baseSql,           setBaseSql]           = useState('');
  // Auto-discover
  const [autoDiscover,      setAutoDiscover]      = useState(false);
  const [institutionQuery,  setInstitutionQuery]  = useState('');
  const [jrxmlParamMap,     setJrxmlParamMap]     = useState('{}');

  useEffect(() => {
    if (!scheduleId) return;
    bulkApi.get(scheduleId).then(r => {
      setPlatformId(r.platformId || '');
      setTpl(r.templateId || POI_DEFAULT);
      setScheduleName(r.scheduleName || '');
      setCategory(r.category || 'CUSTOM');
      setFrequency(r.frequency || 'MONTHLY');
      setRunTime(r.runTime || '07:00');
      setOutputFormat(r.outputFormat || 'EXCEL');
      setRecipients((r.recipients || []).join(', '));
      setNotes(r.notes || '');
      setFileNamingPattern(r.fileNamingPattern || '{REPORT_NAME}_{ENTITY_ID}_{DATE}');
      setLocalOutputPath(r.localOutputPath || '');
      setSourceTable(r.sourceTable || '');
      setIdColumn(r.idColumn || '');
      setIdValues((r.idValues || []).join(', '));
      setBaseSql(r.baseSql || '');
      setAutoDiscover(r.autoDiscover || false);
      setInstitutionQuery(r.institutionQuery || '');
      setJrxmlParamMap(r.jrxmlParamMap || '{}');
      return templateApi.list(r.platformId, 0, 100);
    }).then(d => setTemplates(d?.content || d || []))
    .catch(e => setErr(e.message))
    .finally(() => setLoading(false));
  }, [scheduleId]);

  const submit = async () => {
    if (!scheduleName.trim()) return setErr('Schedule name is required.');
    if (!baseSql.trim()) return setErr('Base SQL is required.');
    const rcpts = recipients.split(',').map(e => e.trim()).filter(Boolean);
    if (rcpts.some(e => !e.includes('@'))) return setErr('One or more email addresses are invalid.');

    let parsedParam = null;
    try { parsedParam = JSON.parse(jrxmlParamMap); } catch { return setErr('JRXML Param Map must be valid JSON.'); }

    setErr(''); setSaving(true);
    try {
      await bulkApi.update(scheduleId, {
        templateId:        tpl === POI_DEFAULT ? undefined : tpl,
        scheduleName,
        category,
        frequency,
        runTime:           frequency !== 'ONE_TIME' ? runTime : undefined,
        outputFormat,
        recipients:        rcpts,
        sourceTable:       sourceTable || undefined,
        idColumn:          idColumn || undefined,
        idValues:          idValues.split(',').map(v => v.trim()).filter(Boolean),
        baseSql,
        autoDiscover,
        institutionQuery:  autoDiscover ? institutionQuery : undefined,
        jrxmlParamMap:     JSON.stringify(parsedParam),
        fileNamingPattern: fileNamingPattern || undefined,
        localOutputPath:   localOutputPath || undefined,
        notes:             notes || undefined,
      });
      onSaved && onSaved();
    } catch (e) {
      setErr(e.message);
    } finally {
      setSaving(false);
    }
  };

  if (loading) return (
    <div style={{ padding: 48, textAlign: 'center', color: C.muted, fontFamily: font.sans }}>
      Loading bulk schedule…
    </div>
  );

  const monoArea = {
    display: 'block', width: '100%', padding: '10px 12px', background: '#0a1520',
    color: '#E2E8F0', border: 'none', outline: 'none', resize: 'vertical',
    fontFamily: font.mono, fontSize: 13, lineHeight: '21px', boxSizing: 'border-box',
    border: '1.5px solid #1e3550', borderRadius: 3,
  };

  const CATS = ['TRANSACTION','BALANCE','STATEMENT','RECONCILIATION','CUSTOM'];

  return (
    <div style={{ fontFamily: font.sans }}>
      {/* Breadcrumb bar */}
      <div style={{ background: C.white, borderBottom: '1px solid ' + C.border,
                    padding: '10px 24px', display: 'flex', alignItems: 'center', gap: 8 }}>
        <button onClick={onCancel}
          style={{ display: 'flex', alignItems: 'center', gap: 6, background: 'none',
                   border: '1px solid ' + C.border, borderRadius: 3, cursor: 'pointer',
                   padding: '5px 12px', fontSize: 13, fontFamily: font.sans,
                   color: C.slate, fontWeight: 600 }}>
         
        </button>
        <span style={{ color: C.muted, fontSize: 13 }}>/</span>
      </div>
      <div style={{ padding: '20px 24px' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 24 }}>
        <div>
        <div>
          <h1 style={{ margin: 0, fontSize: 20, fontWeight: 700, color: C.navyD }}>
            Edit Bulk Schedule
          </h1>
          <p style={{ margin: '2px 0 0', fontSize: 13, color: C.slateL }}>
            {scheduleName || 'Loading…'}
          </p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 300px', gap: 24 }}>
        {/* Main form */}
        <div style={{ background: C.white, border: '1px solid ' + C.border, borderRadius: 4,
                      padding: '28px 32px', boxShadow: '0 1px 8px #1B3A5C08' }}>

          {/* Identity */}
          <Divider label="Schedule Identity" />
          <Field label="Template" hint="Optional">
            <SelectInput value={tpl} onChange={e => setTpl(e.target.value)}>
              <option value={POI_DEFAULT}>📊 Default — Excel / CSV  (no template)</option>
              {templates.map(t => <option key={t.id} value={t.id}>{t.originalName || t.templateName}</option>)}
            </SelectInput>
          </Field>
          <Field label="Schedule Name">
            <TInput value={scheduleName} onChange={e => setScheduleName(e.target.value)}
              placeholder="e.g. All Institution Transaction Reports" />
          </Field>
          <Field label="Category">
            <SelectInput value={category} onChange={e => setCategory(e.target.value)}>
              {CATS.map(c => <option key={c} value={c}>{c.replace(/_/g, ' ')}</option>)}
            </SelectInput>
          </Field>

          {/* Entity Source */}
          <Divider label="Entity Selection" />
          <div style={{ display: 'flex', gap: 0, marginBottom: 14, border: '1.5px solid ' + C.border,
                        borderRadius: 3, overflow: 'hidden', width: 'fit-content' }}>
            {[['manual','📋 Manual IDs'],['sql','⚡ SQL Query']].map(([v,l], i) => (
              <button key={v} onClick={() => setSourceMode(v)}
                style={{ padding: '7px 16px', fontSize: 12.5, fontFamily: font.sans, fontWeight: 700,
                         cursor: 'pointer', border: 'none', outline: 'none',
                         background: sourceMode === v ? C.navy : C.white,
                         color: sourceMode === v ? '#fff' : C.slate,
                         borderRight: i === 0 ? '1px solid ' + C.border : 'none' }}>
                {l}
              </button>
            ))}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <Field label="Source Table">
              <TInput value={sourceTable} onChange={e => setSourceTable(e.target.value)}
                placeholder="e.g. institution_master" />
            </Field>
            <Field label="ID Column">
              <TInput value={idColumn} onChange={e => setIdColumn(e.target.value)}
                placeholder="e.g. institution_code" />
            </Field>
          </div>

          {sourceMode === 'manual' ? (
            <Field label="Entity IDs (comma-separated)">
              <TInput value={idValues} onChange={e => setIdValues(e.target.value)}
                placeholder="STP001, HDFC01, ICICI01" />
            </Field>
          ) : (
            <Field label="Entity Selection Query">
              <textarea value={institutionQuery || ''} rows={4}
                onChange={e => setInstitutionQuery(e.target.value)}
                placeholder={'SELECT institution_code FROM institution_master ORDER BY institution_name'}
                style={monoArea} />
            </Field>
          )}

          {/* Auto-discover */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14, cursor: 'pointer' }}
            onClick={() => setAutoDiscover(!autoDiscover)}>
            <div style={{ width: 36, height: 20, borderRadius: 10,
                          background: autoDiscover ? C.navy : C.border, position: 'relative', transition: 'background 0.2s' }}>
              <div style={{ position: 'absolute', top: 3, left: autoDiscover ? 18 : 3, width: 14, height: 14,
                            borderRadius: '50%', background: C.white, transition: 'left 0.2s' }} />
            </div>
            <span style={{ fontSize: 13, fontWeight: 700, color: autoDiscover ? C.navy : C.slate }}>
              🔍 Auto-discover institutions at run time
            </span>
          </div>

          {autoDiscover && (
            <Field label="Institution Query">
              <textarea value={institutionQuery} rows={4}
                onChange={e => setInstitutionQuery(e.target.value)}
                placeholder="SELECT institution_code, institution_name, product_name FROM institution_master"
                style={monoArea} />
            </Field>
          )}

          {/* Base SQL */}
          <Divider label="Report SQL" />
          <Field label="Base SQL" hint="Use {{ENTITY_ID}} for the entity ID placeholder">
            <textarea value={baseSql} rows={10}
              onChange={e => setBaseSql(e.target.value)}
              placeholder={"SELECT *\nFROM transactions\nWHERE inst_code = '{{ENTITY_ID}}'\nAND txndate >= CURRENT_DATE - 7"}
              style={monoArea} />
          </Field>

          {/* JRXML param map */}
          <Field label="JRXML Parameter Map (JSON)"
            hint="Map JRXML param names to institution query column names">
            <textarea value={jrxmlParamMap} rows={5}
              onChange={e => setJrxmlParamMap(e.target.value)}
              style={{ ...monoArea, fontSize: 12 }} />
          </Field>

          {/* Schedule */}
          <Divider label="Schedule" />
          <Field label="Frequency">
            <Pills options={FREQS} value={frequency} onChange={setFrequency} />
          </Field>
          {frequency !== 'ONE_TIME' && frequency !== 'CUSTOM_CRON' && (
            <Field label="Run Time (UTC)">
              <TInput value={runTime} onChange={e => setRunTime(e.target.value)} type="time" />
            </Field>
          )}

          {/* Delivery */}
          <Divider label="Delivery" />
          <Field label="Output Format">
            <Pills options={FMTS} value={outputFormat} onChange={setOutputFormat} />
          </Field>
          <Field label="Recipients" hint="Optional — comma-separated">
            <TInput value={recipients} onChange={e => setRecipients(e.target.value)}
              placeholder="finance@company.com  (optional)" />
          </Field>
          <FileNamePatternBuilder
            value={fileNamingPattern} onChange={setFileNamingPattern}
            ext={outputFormat === 'PDF' ? '.pdf' : outputFormat === 'EXCEL' ? '.xlsx' : '.csv'}
            localOutputPath={localOutputPath} onLocalOutputPathChange={setLocalOutputPath}
          />
          <Field label="Notes (optional)">
            <TInput value={notes} onChange={e => setNotes(e.target.value)} rows={2}
              placeholder="Schedule scope or delivery notes…" />
          </Field>

          <ErrBox msg={err} />
          <div style={{ display: 'flex', gap: 10, marginTop: 8 }}>
            <PrimaryBtn onClick={submit} loading={saving}>💾 Save Changes</PrimaryBtn>
            <GhostBtn onClick={onCancel}>Cancel</GhostBtn>
          </div>
        </div>

        {/* Sidebar summary */}
        <div style={{ background: '#EFF6FF', border: '1px solid #BFDBFE', borderRadius: 4,
                      padding: '20px 22px', height: 'fit-content', position: 'sticky', top: 20 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: '#1D4ED8', marginBottom: 12 }}>Edit Summary</div>
          {[
            ['Template',   tpl === POI_DEFAULT ? '📊 POI Default' : (templates.find(t => t.id === tpl)?.originalName || '—')],
            ['Schedule',   scheduleName || '—'],
            ['Category',   category.replace(/_/g, ' ')],
            ['Frequency',  frequency.replace(/_/g, ' ')],
            ['Format',     outputFormat],
            ['Auto-disc.', autoDiscover ? '✅ On' : '⚪ Off'],
            ['Email',      recipients.trim() ? recipients.split(',').filter(Boolean).length + ' recipient(s)' : 'Not set'],
          ].map(([k, v]) => (
            <div key={k} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, fontSize: 13 }}>
              <span style={{ color: '#3B82F6', fontWeight: 600 }}>{k}</span>
              <span style={{ color: '#1E3A5F', fontWeight: 700, maxWidth: 140, overflow: 'hidden',
                             textOverflow: 'ellipsis', whiteSpace: 'nowrap', textAlign: 'right' }}>{v}</span>
            </div>
          ))}
          <div style={{ marginTop: 16, padding: '10px 12px', background: '#DBEAFE',
                        borderRadius: 3, fontSize: 12, color: '#1D4ED8' }}>
            💡 Use <code>{'{{ENTITY_ID}}'}</code> in SQL to substitute each entity's ID at run time.
          </div>
        </div>
      </div>
    </div>
      </div>
    </div>
  );
}